mapper.select:
SELECT
  COUNT(CASE WHEN house_type = '오피스텔' THEN 1 END) AS officetel_count,
  COUNT(CASE WHEN house_type IN ('연립', '다세대', '연립다세대') THEN 1 END) AS row_house_count,
  COUNT(CASE WHEN house_type IN ('단독', '다가구') THEN 1 END) AS single_house_count
FROM rental_transactions
WHERE gu_code = #{guCode}
  AND transaction_date >= #{startDate}
  AND transaction_date < #{endDateExclusive}

mapper.delete:
DELETE FROM rental_transactions
WHERE gu_code = #{guCode}
  AND transaction_date >= #{startDate}
  AND transaction_date < #{endDateExclusive}
